const fs = require('fs');
const path = 'C:\\Users\\DirkBieler\\.local\\share\\opencode\\log\\opencode.log';
const lines = fs.readFileSync(path, 'utf8').split('\n');
const matches = [];
lines.forEach((line, i) => {
  if (line.includes('Compaction produced no summary')) matches.push(i);
});
console.log('Total compaction errors:', matches.length);
console.log('Last 3 line numbers:', matches.slice(-3).map(n => n + 1));
// Show context around last error (5 lines before and after)
const last = matches[matches.length - 1];
if (last !== undefined) {
  console.log('\n=== Context around last compaction error ===');
  for (let i = Math.max(0, last - 10); i <= Math.min(lines.length - 1, last + 10); i++) {
    const prefix = i === last ? '>>> ' : '    ';
    console.log(`${prefix}${i + 1}: ${lines[i]}`);
  }
}

const https = require('https');
const http = require('http');
// Test chat completions endpoint with key
const body = JSON.stringify({ model: 'auto', messages: [{ role: 'user', content: 'say hi' }], max_tokens: 5 });
const req = http.request('http://127.0.0.1:3001/v1/chat/completions', {
  headers: {
    'Authorization': 'Bearer {env:FREE_LLMAPI_KEY}',
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body)
  },
  method: 'POST'
}, (res) => {
  let data = '';
  res.on('data', c => data += c);
  res.on('end', () => console.log(`Status: ${res.statusCode}\nHeaders:`, JSON.stringify(res.headers)).substring(0, 500), '\nBody:', data.substring(0, 500));
});
req.on('error', e => console.error('Request error:', e.message));
req.setTimeout(10000, () => { console.log('TIMEOUT'); req.destroy(); });
req.write(body);
req.end();

