1: // session-summary.js — Session-Continuity-Plugin für opencode (eigener Code)
2: // Legt pro beendeter Session eine Summary-Datei unter
3: //   E:\AI-System 3.0\code\sessions\<sessionID>.session.summary.md
4: // an und pflegt den Übersichts-Stub INDEX.md (letzte 50 Einträge).
5: // Robustheit: alles in try/catch, fehlende Payload-Felder werden weggelassen.
6: 
7: import * as fs from "node:fs";
8: import * as path from "node:path";
9: 
10: const SESSIONS_DIR = "E:\\AI-System 3.0\\code\\sessions";
11: const INDEX_MAX = 50;
12: 
13: const sessions = new Map(); // sessionID -> Zustand der Session
14: const roles = new Map(); // messageID -> Rolle (User/Assistant)
15: let projectDir = "";
16: 
17: const now = () => new Date().toISOString();
18: 
19: // Debug-Trace (nur mit SESSION_SUMMARY_DEBUG=1) — dient der Fehlersuche im Test
20: function debug(line) {
21:   if (process.env.SESSION_SUMMARY_DEBUG !== "1") return;
22:   try {
23:     fs.mkdirSync(SESSIONS_DIR, { recursive: true });
24:     fs.appendFileSync(path.join(SESSIONS_DIR, "debug.log"), `[${now()}] ${line}\n`);
25:   } catch {}
26: }
27: 
28: function modelToString(m) {
29:   if (!m) return "";
30:   if (typeof m === "string") return m;
31:   // opencode liefert das Modell als {providerID, modelID|id}
32:   if (m.providerID && (m.modelID || m.id)) return `${m.providerID}/${m.modelID || m.id}`;
33:   return "";
34: }
35: 
36: // Kurzer, einkreisiger Text-Ausschnitt; leere Werte bleiben leer
37: function snippet(value, max = 300) {
38:   if (value == null) return "";
39:   const raw = Array.isArray(value)
40:     ? value.map((p) => (typeof p === "string" ? p : p?.text || "")).join(" ")
41:     : String(value);
42:   const clean = raw.replace(/\s+/g, " ").trim();
43:   if (!clean) return "";
44:   return clean.length > max ? clean.slice(0, max) + " …" : clean;
45: }
46: 
47: function entryFor(sid) {
48:   let e = sessions.get(sid);
49:   if (!e) {
50:     e = { start: "", model: "", directory: "", lastUser: "", lastAction: "", lastText: "", todos: null };
51:     sessions.set(sid, e);
52:   }
53:   return e;
54: }
55: 
56: function timeFromPayload(t) {
57:   if (typeof t !== "number" || !Number.isFinite(t)) return "";
58:   return new Date(t < 1e12 ? t * 1000 : t).toISOString();
59: }
60: 
61: function ensureDir() {
62:   fs.mkdirSync(SESSIONS_DIR, { recursive: true });
63: }
64: 
65: // Atomares Schreiben: erst tmp-Datei, dann rename (überschreibt auf Windows)
66: function atomicWrite(file, content) {
67:   const tmp = `${file}.tmp-${process.pid}-${Date.now()}`;
68:   fs.writeFileSync(tmp, content, "utf8");
69:   try {
70:     fs.renameSync(tmp, file);
71:   } catch {
72:     fs.writeFileSync(file, content, "utf8"); // Fallback, falls rename blockiert ist
73:     try { fs.unlinkSync(tmp); } catch {}
74:   }
75: }
76: 
77: function buildSummary(sid, e, end, reason) {
78:   const lines = ["# Session Summary", ""];
79:   lines.push(`**Session-ID:** ${sid}`);
80:   if (e.start) lines.push(`**Start:** ${e.start}`);
81:   lines.push(`**Ende:** ${end}`);
82:   lines.push(`**Auslöser:** ${reason}`);
83:   const dir = e.directory || projectDir;
84:   if (dir) lines.push(`**Projekt:** ${dir}`);
85:   if (e.model) lines.push(`**Modell/Provider:** ${e.model}`);
86:   if (e.lastUser) lines.push(`**Letzte Nutzer-Nachricht:** ${e.lastUser}`);
87:   if (e.lastAction) lines.push(`**Letzte Aktion:** ${e.lastAction}`);
88:   if (e.lastText) {
89:     lines.push("", "## Letzter Assistenten-Text", "", e.lastText);
90:   }
91:   if (e.todos) {
92:     lines.push("", "## Offene Punkte", "");
93:     const open = e.todos.filter((t) => !t.done);
94:     if (open.length) {
95:       for (const t of open) lines.push(`- ${snippet(t.text || String(t), 200)}`);
96:     } else {
97:       lines.push("- (alle erfassten Todos abgehakt)");
98:     }
99:   }
100:   lines.push("");
101:   return lines.join("\n");
102: }
