104: function updateIndex(sid, e, end) {
105:   let entries = [];
106:   try {
107:     const old = fs.readFileSync(path.join(SESSIONS_DIR, "INDEX.md"), "utf8");
108:     entries = old.split(/\r?\n/).filter((l) => l.startsWith("- "));
109:   } catch {}
110:   const short = snippet(e.lastAction || e.lastUser || "", 80);
111:   entries = entries.filter((l) => !l.includes(`| ${sid} |`));
112:   entries.unshift(`- ${end} | ${sid} | ${e.model || "unbekannt"} | ${short}`);
